const isEnglish=document.documentElement.lang==='en';
const tr=(fr,en)=>isEnglish?en:fr;
const menu=document.querySelector('#menu'),nav=document.querySelector('#links');function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label',tr('Ouvrir le menu','Open menu'))}menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?tr('Fermer le menu','Close menu'):tr('Ouvrir le menu','Open menu'))};nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}});
const english=document.createElement('a');english.href=tr('en.html','index.html');english.hreflang=tr('en','fr');english.lang=english.hreflang;english.textContent=tr('English','Français');nav.append(english);
const need=document.querySelector('#need');
function updateNeed(){const candidate=need.value==='Candidature spontanée';document.querySelector('#org-label').textContent=candidate?tr('Organisation ou statut professionnel','Organisation or professional status'):tr('Organisation','Organisation');document.querySelector('[name=org]').placeholder=candidate?tr('Ex. indépendant, étudiant, salarié','E.g. independent, student, employee'):tr('Entreprise ou institution','Company or institution')}
need.addEventListener('change',updateNeed);
const id=new URLSearchParams(location.search).get('expertise');const selected=allExpertises.find(({item})=>expertiseId(item[1])===id);
if(selected){need.value=selected.group==='Cybersécurité, risques & résilience'?'Cybersécurité & résilience':'Conseil & expertise';document.querySelector('[name=message]').value=tr('Domaine : ','Expertise: ')+(isEnglish?expertiseEnglish[allExpertises.indexOf(selected)][0]:selected.item[1])+' — '}
updateNeed();
document.querySelector('#request').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);document.querySelector('#draft').textContent=`${tr('Objet : ','Subject: ')}${need.selectedOptions[0].textContent}\n${tr('Nom : ','Name: ')}${f.get('nom')}\n${tr('Organisation : ','Organisation: ')}${f.get('org')}\n${tr('E-mail : ','Email: ')}${f.get('email')}\n${f.get('solution')?'Solution : '+f.get('solution')+'\n':''}\n${f.get('message')}`;document.querySelector('#form-result').hidden=false;const status=document.querySelector('#request-status'),button=e.target.querySelector('[type=submit]');button.disabled=true;status.textContent=tr('Enregistrement en cours…','Submitting…');try{const payload=Object.fromEntries(f.entries());payload.language=document.documentElement.lang==='en'?'en':'fr';payload.consent=f.get('consent')==='on';const response=await fetch('/api/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error('request');const result=await response.json();status.textContent=tr('Demande enregistrée localement. Référence : ','Request recorded locally. Reference: ')+result.id+tr('. Notification traitée en différé en recette.','. Notification processed asynchronously in the test environment.');}catch{status.textContent=tr('Enregistrement indisponible : votre demande n’a pas été transmise. Vous pouvez la télécharger ou la copier.','Submission unavailable: your request was not transmitted. You can download or copy it.');}finally{button.disabled=false}};document.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#draft').textContent);document.querySelector('#copy').textContent=tr('Demande copiée','Request copied')}catch{document.querySelector('#copy').textContent=tr('Sélectionnez le texte pour le copier','Select the text to copy it')}};
document.querySelectorAll('[data-need]').forEach(link=>link.addEventListener('click',()=>{document.querySelector('#need').value=link.dataset.need;updateNeed();if(link.dataset.expertise){const message=document.querySelector('[name=message]');const prefix=tr('Domaine : ','Expertise: ')+(isEnglish?(link.closest('article')?.querySelector('h3')?.textContent||link.querySelector('strong')?.textContent||link.dataset.expertise):link.dataset.expertise)+' — ';if(!message.value.trim()||/^(Domaine : |Expertise: )/.test(message.value))message.value=prefix+message.value.replace(/^(?:Domaine : |Expertise: ).*? — /,'')}}));
document.querySelector('#download-request').onclick=()=>{const url=URL.createObjectURL(new Blob([document.querySelector('#draft').textContent],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='demande-DSIG.txt';a.click();URL.revokeObjectURL(url)};

